import{_ as e,o as t,c as l,a2 as i}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"项目开篇","description":"面试通过项目名问问题，核心是项目场景、亮点、概率 + 经验反推，而不是\\"背简历项目名\\"。","frontmatter":{},"headers":[],"relativePath":"面试/项目/index.md","filePath":"面试/项目/index.md","lastUpdated":1793930980000}'),o={name:"面试/项目/index.md"};function r(n,a,s,d,h,c){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="项目开篇" tabindex="-1">项目开篇 <a class="header-anchor" href="#项目开篇" aria-label="Permalink to &quot;项目开篇&quot;">​</a></h1><blockquote><p>面试通过项目名问问题，核心是<strong>项目场景、亮点、概率 + 经验反推</strong>，而不是&quot;背简历项目名&quot;。</p></blockquote><h2 id="📚-章节列表" tabindex="-1">📚 章节列表 <a class="header-anchor" href="#📚-章节列表" aria-label="Permalink to &quot;📚 章节列表&quot;">​</a></h2><ol><li><a href="./项目经验/">项目面试经验总览</a></li><li><a href="./项目经验/01-商户管理SaaS平台">商户管理 SaaS 平台</a></li><li><a href="./项目经验/02-会员服务平台Web-H5">会员服务平台 Web / H5</a></li><li><a href="./项目经验/03-智能风控引擎平台">智能风控引擎平台</a></li><li><a href="./项目经验/04-农业数字化App-IoT大屏">农业数字化项目 App + IoT 大屏</a></li></ol><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>项目开篇强调一个核心观点:<strong>面试官是通过项目名反推你的经验</strong>,不是背简历。</li><li>四个项目:商户管理 SaaS 平台、会员服务平台(Web/H5)、智能风控引擎平台、农业数字化(App + IoT 大屏)——覆盖后台、H5、移动端与大屏。</li><li>每个项目页要准备三层:<strong>做了什么(事实)→ 为什么这么做(判断)→ 遇到什么问题怎么解决(经历)</strong>。</li><li>与技术题的联动:每个技术点都要能挂到某个项目上,避免知识与经历两张皮。</li><li>建议:每个项目准备 3 分钟版本与 10 分钟深挖版本两套。</li></ul>',6)])])}const u=e(o,[["render",r]]);export{p as __pageData,u as default};
